import 'package:graphql/client.dart';

final httpLink = HttpLink('https://api.github.com/graphql');
final authLink = AuthLink(getToken: () async => 'Bearer YOUR_TOKEN');
final link = authLink.concat(httpLink);
final client = GraphQLClient(cache: GraphQLCache(), link: link);

final query = gql(r'''query { viewer { login } }''');
final result = await client.query(QueryOptions(document: query));
print(result.data);
